// The capability type ids (lib/protocol/capability_types.g.dart, generated by
// tools/protogen.py from protocol/schema/capabilities.yaml; decision EXP-20)
// against the schema and HELLO's vectors (protocol/vectors/hello.json).

import 'dart:io';

import 'package:atalaia_app/protocol/capability_types.g.dart';
import 'package:atalaia_app/radio/rf_codec.dart';
import 'package:atalaia_app/security/bytes.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:yaml/yaml.dart';

import '../support/vectors.dart';

void main() {
  test('the generated table is the schema', () {
    final file = File('../protocol/schema/capabilities.yaml');
    final doc = loadYaml(file.readAsStringSync()) as YamlMap;
    final ids = <String, int>{};
    final reserved = <String>{};
    (doc['types'] as YamlMap).forEach((name, spec) {
      ids['$name'] = (spec as YamlMap)['id'] as int;
      if (spec['reserved'] == true) reserved.add('$name');
    });
    expect(capabilityTypeIds, ids);
    expect(reservedCapabilityTypes, reserved);
    expect(capabilityTypeIds['hit'], 10);
    expect(capabilityTypeIds['output'], 11);
    expect(capabilityTypeName(11), 'output');
    expect(capabilityTypeName(0), isNull);
    expect(capabilityTypeName(99), isNull);
  });

  test('HELLO lists type ids, and an unknown one is ignored', () {
    final v = loadVectors('hello.json');
    String names(String name) {
      final c = cases(v, 'valid').firstWhere((c) => c['name'] == name);
      final hello = RfHello.decode(hexDecode(c['cbor'] as String));
      return hello.capabilities.map(capabilityTypeName).join(',');
    }

    expect(
      names('hello_box_capability_ids'),
      'button,keypad,display,led,audio,nfc,hit,output,battery',
    );
    expect(
      names('hello_unknown_capability_id'),
      'button,led,audio,nfc,gps,hit,output,tamper,null',
    );
  });
}
